CREATE TABLE public.trip_inquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL, email text NOT NULL, phone text NOT NULL, trip_name text NOT NULL, travel_date date, travelers integer NOT NULL DEFAULT 2, message text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT trip_inquiries_travelers_range CHECK (travelers BETWEEN 1 AND 20), CONSTRAINT trip_inquiries_status_valid CHECK (status IN ('pending', 'contacted', 'confirmed', 'cancelled'))); GRANT INSERT ON public.trip_inquiries TO anon, authenticated; GRANT ALL ON public.trip_inquiries TO service_role; ALTER TABLE public.trip_inquiries ENABLE ROW LEVEL SECURITY; CREATE POLICY "Visitors can submit trip inquiries" ON public.trip_inquiries FOR INSERT TO anon, authenticated WITH CHECK (char_length(full_name) BETWEEN 2 AND 100 AND char_length(email) BETWEEN 5 AND 254 AND char_length(phone) BETWEEN 7 AND 30 AND char_length(trip_name) BETWEEN 2 AND 120 AND char_length(message) <= 2000 AND travelers BETWEEN 1 AND 20 AND status = 'pending');